function HandoffPanel({session,context}:{session:SessionDTO;context:ContextBridge}){
 const[status,setStatus]=useState<ContextStatusResult>(),[importing,setImporting]=useState(false),[importId,setImportId]=useState(''),[importResult,setImportResult]=useState<ContextHandoffImportResult>(),[imports,setImports]=useState<ContextHandoffListResult>(),[inspectResult,setInspectResult]=useState<ContextHandoffInspectResult>(),[inspectId,setInspectId]=useState(''),[error,setError]=useState<BridgeClientError>(),[busy,setBusy]=useState(false),mounted=useRef(true)
 useEffect(()=>{mounted.current=true;const load=async()=>{try{const s=await context.status({sessionId:session.id});if(mounted.current)setStatus(s)}catch(e){if(mounted.current)setError(problem(e))}try{const r=await context.handoffListImports({targetSessionId:session.id});if(mounted.current)setImports(r)}catch(e){if(mounted.current)setError(problem(e))}};void load();return()=>{mounted.current=false}},[session.id,context])
 const doImport=async()=>{if(!importId.trim())return;setBusy(true);setImporting(true);setError(undefined);setImportResult(undefined);try{const r=await context.handoffImport({capsuleId:importId.trim(),targetSessionId:session.id});if(mounted.current){setImportResult(r);const updated=await context.handoffListImports({targetSessionId:session.id});if(mounted.current)setImports(updated)}}catch(e){if(mounted.current)setError(problem(e))}finally{if(mounted.current){setBusy(false);setImporting(false)}}}
 const doInspect=async()=>{if(!inspectId.trim())return;setBusy(true);setError(undefined);setInspectResult(undefined);try{const r=await context.handoffInspect({capsuleId:inspectId.trim()});if(mounted.current)setInspectResult(r)}catch(e){if(mounted.current)setError(problem(e))}finally{if(mounted.current)setBusy(false)}}
 const doRevoke=async(id:string)=>{setBusy(true);setError(undefined);try{await context.handoffRevoke({capsuleId:id});if(mounted.current){const updated=await context.handoffListImports({targetSessionId:session.id});if(mounted.current)setImports(updated)}}catch(e){if(mounted.current)setError(problem(e))}finally{if(mounted.current)setBusy(false)}}
 const doCompactPreview=async()=>{setBusy(true);setError(undefined);try{await context.compactPreview({sessionId:session.id});if(mounted.current){const s=await context.status({sessionId:session.id});if(mounted.current)setStatus(s)}}catch(e){if(mounted.current)setError(problem(e))}finally{if(mounted.current)setBusy(false)}}
 return <div className="handoff-panel" style={{padding:'12px 18px',borderBottom:'1px solid var(--border)'}}><h3 style={{margin:'0 0 8px',fontSize:'16px'}}>上下文与 Handoff</h3>{status&&<div style={{marginBottom:'8px',fontSize:'13px',color:'var(--text-2)'}}><span>逻辑 Token：{status.canonicalLogicalTokens}</span> · <span>Tokenizer：{status.canonicalTokenizerId}@{status.canonicalTokenizerRevision}</span> · <span>窗口：{status.modelContextWindow}</span> · <span>使用率：{(status.budgetUsage*100).toFixed(1)}%</span>{status.isCompacting&&<span style={{color:'var(--accent)'}}> · 压缩中</span>}</div>}<div style={{marginBottom:'8px'}}><button disabled={busy} onClick={()=>void doCompactPreview()}>{busy?'处理中…':'生成压缩预览'}</button></div><div style={{marginBottom:'8px'}}><label style={{fontSize:'13px',display:'block',marginBottom:'4px'}}>导入 Handoff Capsule（输入 Capsule ID）</label><div style={{display:'flex',gap:'8px'}}><input value={importId} onChange={e=>setImportId(e.target.value)} placeholder="01J..." style={{flex:'1'}}/><button disabled={busy||importing||!importId.trim()} onClick={()=>void doImport()}>{importing?'导入中…':'导入'}</button></div>{importResult&&<div style={{marginTop:'4px',fontSize:'12px',color:importResult.alreadyImported?'var(--text-2)':'var(--green)'}}>{importResult.alreadyImported?'已导入（幂等）':'导入成功'} · 摘要有效：{importResult.digestValid?'是':'否'}{importResult.humanSummary&&<span> · {importResult.humanSummary.slice(0,80)}</span>}</div>}</div><div style={{marginBottom:'8px'}}><label style={{fontSize:'13px',display:'block',marginBottom:'4px'}}>查看 Capsule（输入 Capsule ID）</label><div style={{display:'flex',gap:'8px'}}><input value={inspectId} onChange={e=>setInspectId(e.target.value)} placeholder="01J..." style={{flex:'1'}}/><button disabled={busy||!inspectId.trim()} onClick={()=>void doInspect()}>查看</button></div>{inspectResult&&<div style={{marginTop:'4px',fontSize:'12px',color:'var(--text-2)'}}>状态：{inspectResult.status} · 来源会话：{inspectResult.sourceSessionId.slice(0,8)}…{inspectResult.sourceDeleted&&<span style={{color:'var(--red)'}}> · 源已删除</span>}{inspectResult.humanSummary&&<div style={{marginTop:'4px',whiteSpace:'pre-wrap'}}>{inspectResult.humanSummary}</div>}</div>}</div>{imports&&imports.items.length>0&&<div><label style={{fontSize:'13px',display:'block',marginBottom:'4px'}}>已导入的 Capsule（{imports.items.length}）</label><ul style={{listStyle:'none',padding:0,margin:0}}>{imports.items.map(c=><li key={c.capsuleId} style={{fontSize:'12px',padding:'4px 0',display:'flex',justifyContent:'space-between',alignItems:'center'}}><span>{c.capsuleId.slice(0,12)}… · {c.status}</span><button disabled={busy} onClick={()=>void doRevoke(c.capsuleId)} style={{fontSize:'11px'}}>撤销</button></li>)}</ul></div>}{error&&<div className="error" role="alert" style={{marginTop:'8px'}}><b>{error.message}</b><span>代码 {error.code}</span></div>}</div>
}
type AttachmentItem=AttachmentListResult['items'][number]
function AttachmentPanel({attachments,projectId,sessionId}:{attachments:AttachmentBridge;projectId:string;sessionId:string}){
 const[items,setItems]=useState<AttachmentItem[]>([]),[busy,setBusy]=useState(false),[error,setError]=useState<BridgeClientError>(),[notice,setNotice]=useState(''),[deleteId,setDeleteId]=useState<string>(),fileRef=useRef<HTMLInputElement>(null),mounted=useRef(true)
 const load=async()=>{try{const r=await attachments.list({projectId});if(mounted.current)setItems(r.items.filter(item=>item.sessionId===sessionId))}catch(e){if(mounted.current)setError(problem(e))}}
 useEffect(()=>{mounted.current=true;void load();return()=>{mounted.current=false}},[attachments,projectId,sessionId])
 const onFile=async(e:React.ChangeEvent<HTMLInputElement>)=>{const files=Array.from(e.target.files??[]);try{if(!files.length)return;setBusy(true);setError(undefined);const{uploaded,skipped}=await ingestAttachments(attachments,projectId,sessionId,files,progress=>setNotice(`${progress.name} · ${progress.percent}%`));if(mounted.current){setNotice(`已上传 ${uploaded} 个文件${skipped.length?`；已跳过 ${skipped.length} 个`:''}`);void load()}}catch(e){if(mounted.current)setError(problem(e))}finally{if(mounted.current)setBusy(false);e.target.value='';if(fileRef.current)fileRef.current.value=''}}
 const del=async()=>{if(!deleteId)return;setBusy(true);try{const attempt=createMutationAttempt('attachment.delete',{attachmentId:deleteId});await attachments.delete(attempt.payload as{attachmentId:string},{attempt});if(mounted.current){setDeleteId(undefined);void load()}}catch(e){if(mounted.current)setError(problem(e))}finally{if(mounted.current)setBusy(false)}}
 const fmtSize=(n:number)=>n<1024?`${n} B`:n<1048576?`${(n/1024).toFixed(1)} KB`:`${(n/1048576).toFixed(1)} MB`
 return <div style={{padding:'12px 18px',borderBottom:'1px solid var(--border)'}}><div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:'8px'}}><h3 style={{margin:'0',fontSize:'16px'}}>附件</h3><input ref={fileRef} type="file" multiple style={{display:'none'}} onChange={e=>void onFile(e)} accept={ATTACHMENT_ACCEPT}/><button disabled={busy} onClick={()=>fileRef.current?.click()}>{busy?'处理中…':'添加附件（≤10 MiB）'}</button></div>{notice&&<p role="status" style={{fontSize:'12px',color:'var(--green)',margin:'0 0 8px'}}>{notice}</p>}{error&&<div className="error" role="alert" style={{marginBottom:'8px'}}><b>{error.message}</b></div>}{items.length?<ul style={{listStyle:'none',padding:0,margin:0}}>{items.map(a=><li key={a.attachmentId} style={{fontSize:'12px',padding:'6px 0',display:'flex',justifyContent:'space-between',alignItems:'center',borderBottom:'1px solid var(--border)'}}><div><b>{a.originalName}</b> · {fmtSize(a.size)} · {a.mime}</div><div style={{display:'flex',gap:'8px',alignItems:'center'}}>{a.parseStatus==='succeeded'?<span style={{color:'var(--green)'}}>解析成功 ({a.parsedTextBytes} B)</span>:a.parseStatus==='failed'?<span style={{color:'var(--red)'}}>解析失败</span>:<span style={{color:'var(--text-2)'}}>{a.parseStatus}</span>}<button disabled={busy} onClick={()=>setDeleteId(a.attachmentId)} style={{fontSize:'11px'}}>删除</button></div></li>)}</ul>:<p style={{fontSize:'13px',color:'var(--text-2)'}}>还没有附件。支持文本、代码、JSON、Markdown 等格式（≤10 MiB）。</p>}<ConfirmDialog open={!!deleteId} title="删除附件？" description="此附件将被永久删除，此操作不可撤销。" busy={busy} onCancel={()=>setDeleteId(undefined)} onConfirm={()=>void del()}/></div>
}
